package com.bank.batch;

import java.util.logging.*;

public class BaseLauncher {
    protected static final Logger log = Logger.getLogger("BankLog");

    // STATIC method — can be HIDDEN by a subclass, never overridden.
    public static String describe() {
        return "BaseLauncher.describe() [static — bound to BaseLauncher]";
    }

    // INSTANCE method — CAN be overridden (dynamic dispatch).
    public void settle() {
        log.info("BaseLauncher.settle() [instance — base settlement]");
    }

    // A real static main could live here too; it would be HIDDEN, not overridden, by subclasses.
    public static void main(String[] args) {
        log.info("BaseLauncher.main() running — JVM used THIS class's static main.");
    }
}
