package com.bank.batch;

public class SpecialLauncher extends BaseLauncher {

    // HIDING: same signature static method. NOT an override. @Override here is a COMPILE ERROR.
    public static String describe() {
        return "SpecialLauncher.describe() [static — HIDES BaseLauncher's]";
    }

    // OVERRIDING: instance method genuinely overrides the parent's (dynamic dispatch).
    @Override
    public void settle() {
        log.info("SpecialLauncher.settle() [instance — OVERRIDES base, special settlement]");
    }

    // Subclass may declare its OWN static main; it HIDES the parent's, not overrides it.
    public static void main(String[] args) {
        log.info("SpecialLauncher.main() running — JVM used THIS class's static main.");
    }
}
