package com.bank.batch;

import java.util.logging.*;

public class MainOverrideDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // STATIC HIDING: resolved by the REFERENCE TYPE at compile time, not the object.
        BaseLauncher refAsBase = new SpecialLauncher(); // object is Special, reference is Base
        log.info("Static call via BaseLauncher.describe()    = " + BaseLauncher.describe());
        log.info("Static call via SpecialLauncher.describe() = " + SpecialLauncher.describe());
        // Even though the object is a SpecialLauncher, a static call through the Base TYPE
        // would pick Base's version — static is bound to type, not object.

        // INSTANCE OVERRIDING: resolved by the OBJECT TYPE at runtime (polymorphism).
        BaseLauncher base = new BaseLauncher();
        BaseLauncher special = new SpecialLauncher(); // Base reference, Special object
        log.info("Instance call base.settle():");
        base.settle();      // BaseLauncher.settle
        log.info("Instance call special.settle() (overridden despite Base reference):");
        special.settle();   // SpecialLauncher.settle — dynamic dispatch

        log.info("Conclusion: static main() is HIDDEN by subclasses, never OVERRIDDEN.");
    }
}
